If $L$ is a sorted list of elements and $x$ is an element in $L$, we use $\mathit{next}_L(x)$ and $\mathit{prev}_L(x)$ to denote the successor and the predecessor, respectively, of $x$ in $L$. We use $\bot$ to denote the end-of-list element. A \emph{segment} of $L$ is a sublist of consecutive elements. For convenience, we may handle a list as set (and write, e.g., $x\in L$).  

\section{Properties of $4$-cuts in $3$-edge-connected graphs}
\label{section:structure-of}

\subsection{Implied $4$-cuts, and cyclic families of $4$-cuts}

\begin{definition}[Implicating Sequence]
\label{definition:implied_4cut}
\normalfont
Let $\mathcal{C}$ be a collection of $4$-cuts of $G$, let $p_1,\dots,p_{k+1}$ be a sequence of pairs of edges, and let $C_1,\dots,C_k$ be a sequence of $4$-cuts from $\mathcal{C}$, such that $C_i=p_i\cup p_{i+1}$ for every $i\in\{1,\dots,k\}$. Then $C_1,\dots,C_k$ is called an implicating sequence of $\mathcal{C}$. Furthermore, if $C=p_1\cup p_{k+1}$ is a $4$-cut of $G$, then we say that $\mathcal{C}$ implies $C$ through the pair of edges $p_1$ (or equivalently: through the pair of edges $p_{k+1}$).
\end{definition}

We extend the terminology of Definition~\ref{definition:implied_4cut} as follows. Let $\mathcal{C}$ and $\mathcal{C}'$ be two collections of $4$-cuts such that every $4$-cut in $\mathcal{C}'$ is implied by $\mathcal{C}$. Then we say that $\mathcal{C}$ implies the collection of $4$-cuts $\mathcal{C}'$.

\begin{lemma}
\label{lemma:implied_from_union}
Let $\mathcal{C}$ be a collection of $4$-cuts, and let $C$ and $C'$ be two $4$-cuts such that $C\in\mathcal{C}$ and $\mathcal{C}$ implies $C'$ through a pair of edges $p$. Suppose that $\{C,C'\}$ implies a $4$-cut $C''$ through $p$. Then $\mathcal{C}$ implies $C''$ through $p$.
\end{lemma}

\section{Concepts defined on DFS-tree}
\label{section:DFS}

\subsection{Basic definitions}
\label{subsection:basic-dfs}
Let $T$ be a DFS-tree of $G$ with start vertex $r$ \cite{DBLP:journals/siamcomp/Tarjan72}. We identify the vertices of $G$ with their order of visit by the DFS. (Thus, $r=1$, and the last vertex visited by $G$ is $n$.) For a vertex $v\neq r$ of $G$, we let $p(v)$ denote the parent of $v$ on $T$... If $v$ lies on the tree-path $T[r,u]$, then we say that $v$ is an ancestor of $u$ (equivalently, $u$ is a descendant of $v$)... If $v$ is an ancestor of $u$ such that $v\neq u$, then we say that $v$ is a proper ancestor of $u$ (equivalently, $u$ is a proper descendant of $v$)...

... Thus, the non-tree edges of $G$ are called ``back-edges"... For a vertex $v\neq r$, we say that a back-edge $(x,y)$ leaps over $v$ if $x$ is a descendant of $v$ and $y$ is a proper ancestor of $v$. We let $B(v)$ denote the set of the back-edges that leap over $v$.

Let $v\neq r$ be a vertex. We let $\mathit{bcount}(v)$ denote the number of back-edges that leap over $v$ (i.e., $\mathit{bcount}(v)=|B(v)|$).

\subsubsection{$\mathit{low}$ and $\mathit{high}$ edges}
Now let $(x_1,y_1),\dots,(x_k,y_k)$ be the list of the back-edges in $B(v)$ sorted in increasing order w.r.t. their lower endpoint... Then (w.r.t. this sorting) we call $(x_i,y_i)$ the $\mathit{low}_i$-edge of $v$... The lower endpoint of the $\mathit{low}_i$-edge of $v$ is called the $\mathit{low}_i$ point of $v$, and we denote it as $\mathit{low}_i(v)$ (i.e., we have $\mathit{low}_i(v)=y_i$)... Of particular importance is the $\mathit{low}_1$ point of $v$, which we may simply denote as $\mathit{low}(v)$.

Now let $v\neq r$ be a vertex, and let $(x_1,y_1),\dots,(x_k,y_k)$ be the list of the back-edges in $B(v)$ sorted in decreasing order w.r.t. their lower endpoint... Then (w.r.t. this sorting) we call $(x_i,y_i)$ the $\mathit{high}_i$-edge of $v$... The lower endpoint of the $\mathit{high}_i$-edge of $v$ is called the $\mathit{high}_i$ point of $v$, and we denote it as $\mathit{high}_i(v)$ (i.e., we have $\mathit{high}_i(v)=y_i$)... Of particular importance is the $\mathit{high}_1$ point of $v$, which we may simply denote as $\mathit{high}(v)$. Also, we denote the $\mathit{high}_1$-edge of $v$ as $e_\mathit{high}(v)$.

\subsubsection{Maximum points, leftmost and rightmost edges}
Let $v\neq r$ be a vertex. We let $M(v)$ denote the maximum vertex that is an ancestor of the higher endpoints of the back-edges in $B(v)$...
For every vertex $x$, we let $M^{-1}(x)$ denote the list of all vertices $v$ with $M(v)=x$, sorted in decreasing order...
For every vertex $v\in M^{-1}(x)$, we let $\mathit{nextM}(v)$ and $\mathit{prevM}(v)$ denote the successor and the predecessor, respectively, of $v$ in $M^{-1}(x)$.

We extend the concept of the $M$ points in general sets of back-edges. Thus, if $S$ is a set of back-edges, then we let $M(S)$ denote the nearest common ancestor of the higher endpoints of the back-edges in $S$. (Thus, we have $M(v)=M(B(v))$.)

Let $v\neq r$ be a vertex, and let $(x_1,y_1),\dots,(x_k,y_k)$ be the list of the back-edges in $B(v)$ sorted in increasing order w.r.t. their higher endpoint... Then we call $(x_i,y_i)$ the $i$-th leftmost edge of $v$. We denote $x_i$ as $L_i(v)$, and we call it the $i$-th leftmost point of $v$. Of particular importance is the first leftmost edge of $v$, which we denote as $e_L(v)$. On the other hand, let $(x_1,y_1),\dots,(x_k,y_k)$ be the list of the back-edges in $B(v)$ sorted in decreasing order w.r.t. their higher endpoint... Then we call $(x_i,y_i)$ the $i$-th rightmost edge of $v$. We denote $x_i$ as $R_i(v)$, and we call it the $i$-th rightmost point of $v$. Of particular importance is the first rightmost edge of $v$, which we denote as $e_R(v)$.

\subsection{Computing the $M$ points}
\label{subsection:M}

\begin{proposition}
\label{proposition:computing-M(B(v)-S)}
Let $(v_1,S_1),\dots,(v_N,S_N)$ be a collection of pairs of vertices and sets of back-edges, such that $v_i\neq r$ and $\emptyset\neq S_i\subseteq B(v_i)$ for every $i\in\{1,\dots,N\}$. Then the values $M(B(v_1)\setminus{S_1}),\dots,M(B(v_N)\setminus{S_N})$ can be computed in $O(m+|S_1|+\dots+|S_N|)$ time in total.
\end{proposition}

\subsection{Segments of vertices that have the same $\mathit{high}$ point}
\label{subsection:segments}
Let $x$ be a vertex of $G$, and let $H(x)$ be the list of all vertices $v\neq r$ such that $\mathit{high}(v)=x$, sorted in decreasing order. For a vertex $v\in H(x)$, we let $S(v)$ denote the segment of $H(x)$ that contains $v$ and is maximal w.r.t. the property that its elements are related as ancestor and descendant.

\section{Computing a complete collection of $4$-cuts}
\label{section:computing-4-cuts}

\subsection{Min-max vertex queries}
\label{subsection:mim-max-queries}

\begin{lemma}
\label{lemma:W-queries}
Let $W_1,\dots,W_k$ be a collection of pairwise disjoint sets of vertices. Let $q(i_1,z_1),\dots,q(i_N,z_N)$ be a set of queries of the form $q(i,z)\equiv$`` given an index $i\in\{1,\dots,k\}$ and a vertex $z$, find the greatest vertex $w\in W_i$ such that $w\leq z$". Then, Algorithm~\ref{algorithm:W-queries} answers all those queries in $O(n+N)$ time. 
\end{lemma}

\begin{algorithm}[t!]
\caption{\textsf{Given a collection $W_1,\dots,W_k$ of pairwise disjoint sets of vertices, answer a set of queries $q(i_1,z_1),\dots,q(i_N,z_N)$, where $q(i_t,z_t)$, for every $t\in\{1,\dots,N\}$, asks for the greatest vertex $w\in W_{i_t}$ such that $w\leq z_t$.}}
\label{algorithm:W-queries}
\LinesNumbered
\DontPrintSemicolon
\tcp{$W_1,\dots,W_k$ is a collection of pairwise disjoint sets of vertices}
\ForEach{$i\in\{1,\dots,k\}$}{
  sort $W_i$ in decreasing order\;
}
\ForEach{$i\in\{1,\dots,k\}$}{
  initialize $Q(i)\leftarrow\emptyset$\;
}
\ForEach{$t\in\{1,\dots,N\}$}{
  insert a tuple $(z_t,t)$ into $Q(i_t)$\;
}
\tcp{$Q(i)$ contains a tuple of the form $(z,t)$ if and only if the query $q(i_t,z_t)$ has $i_t=i$ and $z_t=z$. The first component of a tuple in $Q(i)$ stores the vertex of the respective query, and the second component stores a pointer to the query. The information, that we have to search in the set $W_i$ for the answer to this query, is given precisely by the index $i$ of this bucket of tuples}
\ForEach{$i\in\{1,\dots,k\}$}{
  sort $Q(i)$ in decreasing order w.r.t. the first component of its elements\; 
}
\ForEach{$i\in\{1,\dots,k\}$}{
\label{line:W-queries-for}
  let $w$ be the first element of $W_i$\;
  let $p$ be the first element of $Q(i)$\;
  \While{$p\neq\bot$}{
    let $p=(z,t)$\;
    \While{$w\neq\bot$ \textbf{and} $w>z$}{
      $w\leftarrow\mathit{next}_{W_i}(w)$\;
    }
    the answer to $q(i_t,z_t)$ is $w$\;
    $p\leftarrow\mathit{next}_{Q(i)}(p)$\;
  }
}
\end{algorithm}

\section{Computing Type-2 $4$-cuts}
\label{section:type-2}

\begin{lemma}
\label{lemma:type2cuts}
Let $u,v$ be two vertices such that $v$ is a proper ancestor of $u$ with $v\neq r$. Then there exist two distinct back-edges $e_1,e_2$ such that $\{(u,p(u)),(v,p(v)),e_1,e_2\}$ is a $4$-cut if and only if either $(1)$ $B(v)=B(u)\sqcup\{e_1,e_2\}$, or $(2)$ $B(v)\sqcup\{e_1\}=B(u)\sqcup\{e_2\}$, or $(3)$ $B(u)=B(v)\sqcup\{e_1,e_2\}$. 
\end{lemma}

Based on Lemma~\ref{lemma:type2cuts}, we distinguish three different cases for Type-2 $4$-cuts of the form $\{(u,p(u)),(v,p(v)),e_1,e_2\}$, where $v$ is ancestor of $u$ and $e_1,e_2$ are back-edges...

\subsection{The case $B(v)\sqcup\{e_1\}=B(u)\sqcup\{e_2\}$}
\label{subsubsection:case_B(v)cup=B(u)cup}
Let $\{(u,p(u)),(v,p(v)),e_1,e_2\}$ be a Type-$2$ $4$-cut such that $e_1\in B(u)$ and $e_2\in B(v)$. Then, by Lemma~\ref{lemma:type2cuts} we have that $B(u)\sqcup\{e_2\}=B(v)\sqcup\{e_1\}$, and we call this a Type-$2ii$ $4$-cut.

\begin{algorithm}[h!]
\caption{\textsf{Compute a collection of Type-$2ii$ $4$-cuts, which implies all Type-$2ii$ $4$-cuts}}
\label{algorithm:type2-2}
\LinesNumbered
\DontPrintSemicolon
\ForEach{vertex $v\neq r$}{
\label{line:type-2-2-compute1}
  compute $M_L(v)=M(B(v)\setminus\{e_L(v)\})$ and $M_R(v)=M(B(v)\setminus\{e_R(v)\})$\;
}
\ForEach{vertex $u\neq r$}{
\label{line:type-2-2-compute2}
  compute $M_\mathit{high}(u)=M(B(u)\setminus\{e_\mathit{high}(u)\})$\;  
}
\ForEach{vertex $v\neq r$}{
  compute the lowest proper descendant $u$ of $v$ with $M(u)\neq M_\mathit{high}(u)=M_L(v)$; denote this vertex as $u_\mathit{highL}(v)$\;
  \label{line:type-2-2-lowest-u}
  compute the lowest proper descendant $u$ of $v$ with $M(u)\neq M_\mathit{high}(u)=M_R(v)$; denote this vertex as $u_\mathit{highR}(v)$\;  
  \label{line:type-2-2-lowest-u-2}
  compute the lowest proper descendant $u$ of $v$ with $M(u)=M_L(v)$; denote this vertex as $u_L(v)$\;
  \label{line:type-2-2-lowest-u-3}
  compute the lowest proper descendant $u$ of $v$ with $M(u)=M_R(v)$; denote this vertex as $u_R(v)$\;
  \label{line:type-2-2-lowest-u-4}
}
\ForEach{vertex $v\neq r$}{
  let $u\leftarrow u_\mathit{highL}(v)$\;
  \If{$\mathit{bcount}(u)=\mathit{bcount}(v)$}{
    mark $\{(u,p(u)),(v,p(v)),e_\mathit{high}(u),e_L(v)\}$ as a Type-$2ii$ $4$-cut\;
    \label{line:type-2-2-mark1}
  }
  let $u\leftarrow u_L(v)$\;
  \If{$M_\mathit{high}(u)=M_L(v)$ \textbf{and} $\mathit{bcount}(u)=\mathit{bcount}(v)$}{
  \label{line:type-2-2-cond1}
    mark $\{(u,p(u)),(v,p(v)),e_\mathit{high}(u),e_L(v)\}$ as a Type-$2ii$ $4$-cut\;
    \label{line:type-2-2-mark2}
  }
  let $u\leftarrow\mathit{prevM}(u)$\;
  \label{line:type-2-2-previous}
  \If{$M_\mathit{high}(u)=M_L(v)$ \textbf{and} $\mathit{bcount}(u)=\mathit{bcount}(v)$}{
  \label{line:type-2-2-cond2}
    mark $\{(u,p(u)),(v,p(v)),e_\mathit{high}(u),e_L(v)\}$ as a Type-$2ii$ $4$-cut\;
    \label{line:type-2-2-mark3}
  }
  let $u\leftarrow u_\mathit{highR}(v)$\;
  \If{$\mathit{bcount}(u)=\mathit{bcount}(v)$}{
    mark $\{(u,p(u)),(v,p(v)),e_\mathit{high}(u),e_R(v)\}$ as a Type-$2ii$ $4$-cut\;
    \label{line:type-2-2-mark1'}
  }
  let $u\leftarrow u_R(v)$\;
  \If{$M_\mathit{high}(u)=M_R(v)$ \textbf{and} $\mathit{bcount}(u)=\mathit{bcount}(v)$}{
  \label{line:type-2-2-cond3}
    mark $\{(u,p(u)),(v,p(v)),e_\mathit{high}(u),e_R(v)\}$ as a Type-$2ii$ $4$-cut\;
    \label{line:type-2-2-mark2'}   
  }
  let $u\leftarrow\mathit{prevM}(u)$\;
  \If{$M_\mathit{high}(u)=M_R(v)$ \textbf{and} $\mathit{bcount}(u)=\mathit{bcount}(v)$}{
  \label{line:type-2-2-cond4}
    mark $\{(u,p(u)),(v,p(v)),e_\mathit{high}(u),e_R(v)\}$ as a Type-$2ii$ $4$-cut\;
    \label{line:type-2-2-mark3'}   
  }
}
\end{algorithm}

\begin{proposition}
\label{proposition:type-2-2}
Algorithm~\ref{algorithm:type2-2} computes a collection $\mathcal{C}$ of Type-$2ii$ $4$-cuts, such that every Type-$2ii$ $4$-cut of the form $\{(u,p(u)),(v,p(v)),e_1,e_2\}$, where $B(v)\sqcup\{e_1\}=B(u)\sqcup\{e_2\}$, is implied by $\mathcal{C}$ through the pair of edges $\{(u,p(u)),e_1\}$. Furthermore, Algorithm~\ref{algorithm:type2-2} has a linear-time implementation.
\end{proposition}

\section{Computing Type-3$\beta$ $4$-cuts}
\label{section:type-3b}

\begin{lemma}
\label{lemma:type-3b-cases}
Let $u,v,w$ be three vertices $\neq r$ such that $w$ is proper ancestor of $v$ and $v$ is a proper ancestor of $u$, and let $e$ be a back-edge. Then $C'=\{(u,p(u)),(v,p(v)),(w,p(w)),e\}$ is a $4$-cut if and only if one of the following is true. (See Figure~\ref{figure:type3b}.)
\begin{enumerate}[label=(\arabic*)]
\item{$e\in B(u)\cap B(v)\cap B(w)$ and $B(v)\setminus\{e\}=(B(u)\setminus\{e\})\sqcup(B(w)\setminus\{e\})$}
\item{$e\in B(w)$, $e\notin B(v)\cup B(u)$, and $B(v)=B(u)\sqcup(B(w)\setminus\{e\})$}
\item{$e\in B(u)$, $e\notin B(v)\cup B(w)$, and $B(v)=(B(u)\setminus\{e\})\sqcup B(w)$}
\item{$e\in B(v)$ and $B(v)=(B(u)\sqcup B(w))\sqcup\{e\}$}
\end{enumerate}
\end{lemma}

\subsection{Type-3$\beta ii$ $4$-cuts}
\label{subsection:type-3b-ii}

\subsubsection{Type-3$\beta ii$-$2$ $4$-cuts}

Let $u,v,w$ be three vertices $\neq r$ such that $w$ is proper ancestor of $v$, $v$ is a proper ancestor of $u$, and there is a back-edge $e\in B(w)$ such that $e\notin B(v)\cup B(u)$, $B(v)=B(u)\sqcup(B(w)\setminus\{e\})$ and $M(v)=M(B(w)\setminus\{e\})$. By Lemma~\ref{lemma:type-3b-cases}, we have that $\{(u,p(u)),(v,p(v)),(w,p(w)),e\}$ is a $4$-cut, and we call this a Type-3$\beta$ii-$2$ $4$-cut.

\begin{lemma}
\label{lemma:type3-b-ii-2-info}
Let $u,v,w$ be three vertices such that $(u,v,w)$ induces a Type-3$\beta$ii-$2$ $4$-cut, and let $e$ be the back-edge of the $4$-cut induced by $(u,v,w)$. Then $e$ is either $(L_1(w),l(L_1(w)))$ or $(R_1(w),l(R_1(w)))$. Furthermore, $\mathit{high}(u)=\mathit{high}(v)$, $M(w)\neq M(B(w)\setminus\{e\})$, $w$ is an ancestor of $\mathit{high}(v)$, $\mathit{low}(v)<w$ and $w\leq\mathit{low}(u)$. Finally, if $u'$ is a vertex such that $u\geq u'\geq v$ and $\mathit{high}(u')=\mathit{high}(v)$, then $u'$ is an ancestor of $u$.
\end{lemma}

Now, for every vertex $v\neq r$, let $W(v)$ be the collection of all vertices $w\neq r$ such that: $(1)$ $M(B(w)\setminus\{e_L(w)\})\neq M(w)$, $(2)$ $M(B(w)\setminus\{e_L(w)\})=M(v)$, and $(3)$ $L_1(w)$ is not a descendant of $\mathit{high}(v)$. In particular, if $W(v)\neq\emptyset$, then we define $\mathit{firstW}(v)=\mathit{max}(W(v))$ and $\mathit{lastW}(v)=\mathit{min}(W(v))$.

\begin{lemma}
\label{lemma:w(v)_ancestor_of_high}
Let $v$ and $w$ be two vertices such that $w\in W(v)$. Then $w$ is a proper ancestor of $\mathit{high}(v)$.
\end{lemma}

First, for every vertex $x$, we let $W_0(x)$ denote the list of all vertices $w\neq r$ with $M(w)\neq M(B(w)\setminus\{e_L(w)\})=x$, sorted in decreasing order.

Recall that, for every vertex $x$, we let $H(x)$ denote the list of all vertices $v\neq r$ such that $\mathit{high}(v)=x$, sorted in decreasing order. Then, for every vertex $v\neq r$, we let $S(v)$ denote the segment of $H(\mathit{high}(v))$ that contains $v$ and is maximal w.r.t. the property that its elements are related as ancestor and descendant. Furthermore, we let $U(v)$ denote the subsegment of $S(v)$ that contains all the proper descendants of $v$.
Now, for every vertex $v$ such that $W(v)\neq\emptyset$, we let $U_2(v)$ be the collection of all $u\in U(v)$ such that: either $(1)$ $\mathit{firstW}(v)>\mathit{low}(u)\geq\mathit{lastW}(v)$, or $(2)$ $u$ is the lowest vertex in $U(v)$ such that $\mathit{low}(u)\geq\mathit{firstW}(v)$.

\begin{lemma}
\label{lemma:type3-b-ii-2-u-w}
Let $(u,v,w)$ be a triple of vertices that induces a Type-3$\beta$ii-$2$ $4$-cut, where $L_1(w)$ is not a descendant of $\mathit{high}(v)$. Then $u\in U_2(v)$ and $w\in W(v)$. 
\end{lemma}

\begin{lemma}
\label{lemma:type-3-b-ii-2-L-rel}
Let $(u,v,w)$ be a triple of vertices that induces a Type-3$\beta$ii-$2$ $4$-cut, where $L_1(w)$ is not a descendant of $\mathit{high}(v)$. Let $w'$ be the greatest vertex in $W(v)$ that has $w'\leq\mathit{low}(u)$. Then $(u,v,w')$ also induces a Type-3$\beta$ii-$2$ $4$-cut. Furthermore, if $w'\neq w$, then $B(w)\sqcup\{e_L(w')\}=B(w')\sqcup\{e_L(w)\}$.
\end{lemma}

\begin{algorithm}[H]
\caption{\textsf{Compute the sets $U_2(v)$, for all vertices $v$ such that $W(v)\neq\emptyset$}}
\label{algorithm:type3-b-ii-2-U}
\LinesNumbered
\DontPrintSemicolon
let $\mathcal{V}$ be the collection of all vertices $v$ such that $W(v)\neq\emptyset$\; 
\ForEach{vertex $x$}{
  compute the collection $\mathcal{S}(x)$ of the segments of $H(x)$ that are maximal w.r.t. the property
  that their elements are related as ancestor and descendant\;
}
\ForEach{$v\in\mathcal{V}$}{
  set $U_2(v)\leftarrow\emptyset$\;
}
\ForEach{vertex $x$}{
  \ForEach{segment $S\in\mathcal{S}(x)$}{
    let $v$ be the first vertex in $S$\;
    \While{$v\neq\bot$ \textbf{and} $v\notin\mathcal{V}$}{
      $v\leftarrow\mathit{next}_S(v)$\;
    }
    \lIf{$v=\bot$}{\textbf{continue}}
    let $u\leftarrow\mathit{prev}_S(v)$\;
    \While{$v\neq\bot$}{
      \While{$u\neq\bot$ \textbf{and} $\mathit{low}(u)<\mathit{lastW}(v)$}{
        $u\leftarrow\mathit{prev}_S(u)$\;
      }
      \While{$u\neq\bot$ \textbf{and} $\mathit{low}(u)<\mathit{firstW}(v)$}{
        insert $u$ into $U_2(v)$\;
        $u\leftarrow\mathit{prev}_S(u)$\;
      }
      \If{$u\neq\bot$}{
        insert $u$ into $U_2(v)$\;
      }
      $v\leftarrow\mathit{next}_S(v)$\;
      \While{$v\neq\bot$ \textbf{and} $v\notin\mathcal{V}$}{
        $v\leftarrow\mathit{next}_S(v)$\;
      }      
    }
  }
}
\end{algorithm}

\begin{lemma}
\label{lemma:algorithm:type3-b-ii-2-U}
Algorithm~\ref{algorithm:type3-b-ii-2-U} correctly computes the sets $U_2(v)$, for all vertices $v\neq r$ such that $W(v)\neq\emptyset$. Furthermore, it runs in linear time.
\end{lemma}

\begin{lemma}
\label{lemma:type-3-b-ii-2-L-criterion}
Let $u,v,w$ be three vertices such that $u\in U_2(v)$, $w\in W(v)$, $w\leq\mathit{low}(u)$, and $\mathit{bcount}(v)=\mathit{bcount}(u)+\mathit{bcount}(w)-1$. Then, $e_L(w)\notin B(u)\cup B(v)$, and $B(v)=B(u)\sqcup(B(w)\setminus\{e_L(w)\})$. 
